INSERT INTO products ("id", "partner_id", "sku", "oem_code", "part_brand", "category_id", "name", "slug", "description", "short_specs", "price", "original_price", "stock", "reserved_stock", "weight_g", "width_cm", "height_cm", "depth_cm", "status", "reject_reason", "is_admin_created", "is_featured", "is_hot", "is_new", "sold_count", "view_count", "rating_avg", "rating_count", "warranty_months", "approved_by", "approved_at", "published_at", "created_at", "updated_at", "meta_title", "meta_description", "focus_keyword", "canonical_url", "og_image", "is_indexed", "price_before_tax", "tax_amount", "vat_rate", "oem_code2", "min_stock", "max_stock", "features", "specifications", "car_brand_id", "sale_price", "is_on_sale", "show_on_home", "show_on_promo", "seo_title", "seo_description", "seo_keyword", "video_url", "cost_price", "total_import_value", "location_code", "is_call_price", "is_active", "wholesale_price", "seo_secondary_keywords") VALUES (6914, 1, 'TCA-LIVE-27-1', '97802-25000 / 9780225000', 'Hanon', 27, 'Phin lọc ga Hanon 97802-25000 | 97802-25000', 'phin-loc-ga-hanon-chinh-hang-97802-25000-97802-25000', '<h2>1. Mô Tả Sản Phẩm Phin lọc ga Hanon 97802-25000</h2> <div style="text-align: center; margin: 20px 0;"><img style="max-width: 100%; height: 352px; border-radius: 10px; box-shadow: rgba(0, 0, 0, 0.08) 0px 4px 12px;" src="../../../uploads/products/phin_l_c_gas_hanon_ch_nh_h_ng.jpg" alt="Phin lọc ga Hanon 97802-25000" width="352"></div> <div style="margin: 20px 0px; text-align: left;">Phin lọc ga Hanon (Mã sản phẩm: <strong data-path-to-node="1" data-index-in-node="43">97802-25000 / 97802-25000</strong>) là phụ tùng điện lạnh cao cấp do tập đoàn HANON sản xuất (nhà cung cấp OEM chính thức các dòng xe Hàn Quốc như , ). Sản phẩm đóng vai trò bảo vệ cốt lõi hệ thống điều hòa ô tô với nhiệm vụ lọc sạch tạp chất, cặn bẩn, mạt kim loại và hấp thụ ẩm triệt để trong môi chất lạnh (gas điều hòa). Điều này giúp dòng gas lưu thông tinh khiết, ngăn ngừa nguy cơ tắc nghẽn van tiết lưu, bảo vệ lốc lạnh vận hành bền bỉ và giữ khoang cabin luôn đạt độ lạnh sâu dịu mượt.</div> <h3>2. Thiết Kế Kỹ Thuật & Tương Thích Dòng Xe</h3> <p>Linh kiện <strong>Phin lọc ga Hanon 97802-25000</strong> đóng vai trò vô cùng quan trọng trong việc duy trì nhiệt độ cabin lý tưởng, giúp tối ưu áp suất gas và dòng khí làm mát/sưởi ấm. Được sản xuất trên dây chuyền công nghệ hiện đại, sản phẩm chịu được áp suất làm việc lớn và biến thiên nhiệt độ khắc nghiệt trong khoang động cơ xe <strong>Các dòng xe ô tô thông dụng</strong>.</p> <ul> <li><strong>Lắp đặt chuẩn xác:</strong> Đúng kích thước và chân bắt theo thiết kế nguyên bản của dòng xe Các dòng xe ô tô thông dụng.</li> <li><strong>Vận hành êm ái:</strong> Giảm thiểu tiếng ồn và độ rung lắc khi hệ thống điều hòa hoạt động.</li> <li><strong>Tiết kiệm nhiên liệu:</strong> Giúp lốc lạnh và quạt gió vận hành tối ưu, giảm tải động cơ ô tô.</li> </ul> <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 12px; padding: 20px 24px; margin-top: 28px;"> <h4 style="margin: 0 0 12px; font-size: 15px; font-weight: bold; color: #1a3258;">Cooling Systems- Chuỗi Dịch vụ & Phụ tùng Điều Hòa Ô Tô Chuyên Nghiệp.</h4> <p style="margin: 0 0 8px; font-size: 13.5px; color: #475569;">• Hotline & Zalo tư vấn: <strong style="color: #1a3258;">0705 070 526</strong></p> <p style="margin: 0 0 8px; font-size: 13.5px; color: #475569;">• Email hỗ trợ: <strong style="color: #1a3258;">hotrokhachhang@autopartsvietnam.com</strong></p> <p style="margin: 0; font-size: 13.5px; color: #475569;">• Website chính thức: <a style="color: #1a3258; font-weight: bold;" href="../../../" target="_blank" rel="noopener">https://coolingsystems.vn</a></p> </div>', NULL, 315000, 350000, 999, 0, NULL, NULL, NULL, NULL, 'published', NULL, 0, 0, 0, 0, 0, 8, 0.0, 0, 6, NULL, NULL, NULL, '2026-08-02 19:10:27', '2026-08-12 21:44:20', NULL, 'Phin lọc ga Hanon 97802-25000 Phin lọc ga Hanon (Mã sản phẩm: 97802-25000 / 97802-25000) là phụ tùng điện lạnh cao cấp do tập đoàn...', 'phin lọc ga hanon 97802-25000 | 97802-25000', NULL, NULL, 1, 0, 0, 10, '9780225000', 5, 1000, '<ul> <li><strong>Đạt chuẩn chất lượng OEM:</strong> Sản phẩm Phin lọc ga Hanon 97802-25000 đáp ứng nghiêm ngặt các tiêu chuẩn kỹ thuật của nhà sản xuất phụ tùng ô tô .</li> <li><strong>Vật liệu cao cấp:</strong> Chế tạo từ hợp kim nhôm chịu lực, lõi đồng truyền nhiệt tốt và hợp chất cao su tổng hợp chống lão hóa.</li> <li><strong>Độ tương thích hoàn hảo:</strong> Tương thích chính xác với hệ thống điều hòa xe <strong>Các dòng xe ô tô thông dụng</strong>, không cần gia công hay chỉnh sửa khi thay thế.</li> <li><strong>Độ bền & An toàn:</strong> Kháng ăn mòn hóa chất, hoạt động ổn định và an toàn tuyệt đối trong thời gian dài.</li> </ul>', '<table style="width: 100%; border-collapse: collapse; margin-top: 10px; margin-bottom: 15px; border: 1px solid #e2e8f0;"> <tbody> <tr style="background-color: #f8fafc;"> <td style="padding: 10px 14px; border: 1px solid #e2e8f0; font-weight: bold; width: 35%;">Tên sản phẩm</td> <td style="padding: 10px 14px; border: 1px solid #e2e8f0;">Phin lọc ga Hanon 97802-25000</td> </tr> <tr> <td style="padding: 10px 14px; border: 1px solid #e2e8f0; font-weight: bold;">Mã OEM chính</td> <td style="padding: 10px 14px; border: 1px solid #e2e8f0;"><strong style="color: #1a3258;">97802-25000</strong></td> </tr> <tr style="background-color: #f8fafc;"> <td style="padding: 10px 14px; border: 1px solid #e2e8f0; font-weight: bold;">Danh mục phụ tùng</td> <td style="padding: 10px 14px; border: 1px solid #e2e8f0;">Phin Lọc Ga</td> </tr> <tr> <td style="padding: 10px 14px; border: 1px solid #e2e8f0; font-weight: bold;">Dòng xe tương thích</td> <td style="padding: 10px 14px; border: 1px solid #e2e8f0;">Các dòng xe ô tô thông dụng</td> </tr> <tr style="background-color: #f8fafc;"> <td style="padding: 10px 14px; border: 1px solid #e2e8f0; font-weight: bold;">Tình trạng nhà sản xuất</td> <td style="padding: 10px 14px; border: 1px solid #e2e8f